"""Install the retouched portrait in Borisovskaya's card on the main team page."""
import base64
import datetime
import fcntl
import hashlib
import os
from pathlib import Path
import re
import shutil
import tempfile

DIGEST = "5c304ad15b7b89ce80c0601f4e0a30f7c3f384b7f64a6c1394927cc6b2a8d6a0"
PAYLOAD = ""
OLD = "/assets/team2-v1/dental-borisovskaya-b53ca3fa.webp"
NEW = "/assets/team2-v1/dental-borisovskaya-" + DIGEST[:8] + ".webp"
NAME = "Борисовская Алина Игоревна"


def require(value, message):
    if not value:
        raise ValueError(message)


def install(root, backups):
    image = base64.b64decode(PAYLOAD, validate=True)
    require(hashlib.sha256(image).hexdigest() == DIGEST, 'Не совпала контрольная сумма портрета')
    page = root / 'team/index.html'
    asset = root / NEW.lstrip('/')
    require(page.resolve() == page and asset.resolve() == asset, 'Проверьте пути страницы и портрета')
    lock = os.open(page.parent, os.O_RDONLY)
    try:
        fcntl.flock(lock, fcntl.LOCK_EX)
        original = page.read_bytes()
        html = original.decode('utf-8')
        cards = list(re.finditer(r'<article\b[^>]*\bid="person-borisovskaya"[^>]*>.*?</article>', html, re.S))
        require(len(cards) == 1, 'Карточка Борисовской не найдена однозначно')
        card = cards[0]
        tags = re.findall(r'<img\b[^>]*>', card.group())
        require(len(tags) == 1 and f'alt="{NAME}"' in tags[0], 'Проверьте имя в карточке')
        old_src, new_src = f'src="{OLD}"', f'src="{NEW}"'
        require(tags[0].count(old_src) + tags[0].count(new_src) == 1, 'В карточке уже другой портрет')
        updated = (html[:card.start()] + card.group().replace(old_src, new_src, 1) + html[card.end():]).encode()
        if asset.exists():
            require(asset.read_bytes() == image, 'Конфликт файла портрета')
            if updated == original:
                print('BORISOVSKAYA_BADGE=ALREADY_APPLIED')
                return
        stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        backup = backups / ('borisovskaya-badge-' + stamp)
        backup.mkdir(mode=0o700, parents=True)
        shutil.copy2(page, backup / 'index.html')
        require((backup / 'index.html').read_bytes() == original, 'Страница изменилась при копировании')
        if not asset.exists():
            with tempfile.NamedTemporaryFile(dir=asset.parent, delete=False) as f:
                tmp = Path(f.name)
            try:
                tmp.write_bytes(image)
                tmp.chmod(0o644)
                os.link(tmp, asset)
            finally:
                tmp.unlink(missing_ok=True)
        if updated != original:
            st = page.stat()
            with tempfile.NamedTemporaryFile(dir=page.parent, delete=False) as f:
                tmp = Path(f.name)
            try:
                tmp.write_bytes(updated)
                if os.geteuid() == 0:
                    os.chown(tmp, st.st_uid, st.st_gid)
                tmp.chmod(st.st_mode & 0o7777)
                require(page.read_bytes() == original, 'Страница изменилась, повторите запуск')
                os.replace(tmp, page)
            finally:
                tmp.unlink(missing_ok=True)
        require(page.read_bytes() == updated and asset.read_bytes() == image, 'Ошибка проверки установленного портрета')
        print('BORISOVSKAYA_BADGE=PASS; CHANGE=ONE_PORTRAIT')
        print('BACKUP=' + str(backup))
    finally:
        os.close(lock)


if __name__ == '__main__':
    install(Path('/var/www/azmednsk-preview'), Path('/var/backups/azmednsk'))
    print('URL=https://azmednsk.ru/team/#person-borisovskaya')
